service.method:
SELECT HOUSE_CODE , COMPANY_CODE , CONT_NO , CONT_GL_SEQ , ADD_DATE , ADD_TIME , ADD_USER_ID , CHANGE_DATE , CHANGE_TIME , CHANGE_USER_ID , DEL_FLAG , CONT_TYPE , CONT_SUBJECT , STATUS , CATEGORY , CREATOR , CONT_METHOD , CONT_FORM_NO , CONT_DATE , CONT_FROM , CONT_TO , EXPIRED_ALARM , SUMMARY , CONT_AMT , SIGN_ORDER , SOURCE_NO , REMARK FROM SSCGL WHERE HOUSE_CODE = ${session.HOUSE_CODE} AND #DB_OWNER#nvl(DEL_FLAG, 'N') = 'N'
AND CONT_NO = ${CONT_NO} AND CONT_GL_SEQ = ${CONT_GL_SEQ}
AND SOURCE_NO = ${SOURCE_NO}


INSERT
  INTO SSCGL (
       HOUSE_CODE
     , COMPANY_CODE
     , CONT_NO
     , CONT_GL_SEQ
     , ADD_DATE
     , ADD_TIME
     , ADD_USER_ID
     , CHANGE_DATE
     , CHANGE_TIME
     , CHANGE_USER_ID
     , DEL_FLAG
     , CONT_TYPE
     , CONT_SUBJECT
     , STATUS
     , CATEGORY
     , CREATOR
     , CONT_METHOD
     , CONT_FORM_NO
     , CONT_DATE
     , CONT_FROM
     , CONT_TO
     , EXPIRED_ALARM
     , SUMMARY
     , CONT_AMT
     , SIGN_ORDER
     , SOURCE_NO
     , REMARK
  )
VALUES (
       ${session.HOUSE_CODE}
     , ${session.COMPANY_CODE}
     , ${CONT_NO}
     , ${CONT_GL_SEQ}
     , ${current.DATE}
     , ${current.TIME}
     , ${session.ID}
     , ${current.DATE}
     , ${current.TIME}
     , ${session.ID}
     , 'N'
     , ${CONT_TYPE}
     , ${CONT_SUBJECT}
     , ${STATUS}
     , ${CATEGORY}
     , ${CREATOR}
     , ${CONT_METHOD}
     , ${CONT_FORM_NO}
     , ${CONT_DATE}
     , ${CONT_FROM}
     , ${CONT_TO}
     , ${EXPIRED_ALARM}
     , ${SUMMARY}
     , ${CONT_AMT}
     , ${SIGN_ORDER}
     , ${SOURCE_NO}
     , ${REMARK}
)


UPDATE SSCGL
   SET DEL_FLAG = 'Y'
     , CHANGE_DATE = ${current.DATE}
     , CHANGE_TIME = ${current.TIME}
     , CHANGE_USER_ID = ${session.ID}
WHERE HOUSE_CODE   = ${session.HOUSE_CODE}
  AND COMPANY_CODE = ${session.COMPANY_CODE}
  AND CONT_NO      = ${CONT_NO}
  AND CONT_GL_SEQ  = ${CONT_GL_SEQ}


DELETE
  FROM SSCGL
WHERE HOUSE_CODE   = ${session.HOUSE_CODE}
  AND COMPANY_CODE = ${session.COMPANY_CODE}
  AND CONT_NO      = ${CONT_NO}
  AND CONT_GL_SEQ  = ${CONT_GL_SEQ}


INSERT
  INTO SSCSI (
       HOUSE_CODE
     , CONT_NO
     , CONT_GL_SEQ
     , SIGNER_ID
     , ADD_DATE
     , ADD_TIME
     , ADD_USER_ID
     , CHANGE_DATE
     , CHANGE_TIME
     , CHANGE_USER_ID
     , DEL_FLAG
     , SEQ
     , SIGNER_COMPANY_CODE
     , FIXED_SIGNER_NAME
     , FIXED_SIGNER_EMAIL
     , FIXED_SIGNER_PHONE
     , FIXED_IRS_NO
     , FIXED_CATEGORY
  )
VALUES (
       ${session.HOUSE_CODE}
     , ${CONT_NO}
     , ${CONT_GL_SEQ}
     , ${SIGNER_ID}
     , ${current.DATE}
     , ${current.TIME}
     , ${session.ID}
     , ${current.DATE}
     , ${current.TIME}
     , ${session.ID}
     , 'N'
     , ${SEQ}
     , ${SIGNER_COMPANY_CODE}
     , ${FIXED_SIGNER_NAME}
     , ${FIXED_SIGNER_EMAIL}
     , ${FIXED_SIGNER_PHONE}
     , ${FIXED_IRS_NO}
     , ${FIXED_CATEGORY}
)


UPDATE SSCSI
   SET CHANGE_DATE         = ${current.DATE}
     , CHANGE_TIME         = ${current.TIME}
     , CHANGE_USER_ID      = ${session.ID}
     , SIGNER_ID           = #DB_OWNER#nvl(${SIGNER_ID},           SIGNER_ID)
     , SEQ                 = #DB_OWNER#nvl(${SEQ},                 SEQ)
     , SIGNER_COMPANY_CODE = #DB_OWNER#nvl(${SIGNER_COMPANY_CODE}, SIGNER_COMPANY_CODE)
     , FIXED_SIGNER_NAME   = #DB_OWNER#nvl(${FIXED_SIGNER_NAME},   FIXED_SIGNER_NAME)
     , FIXED_SIGNER_EMAIL  = #DB_OWNER#nvl(${FIXED_SIGNER_EMAIL},  FIXED_SIGNER_EMAIL)
     , FIXED_SIGNER_PHONE  = #DB_OWNER#nvl(${FIXED_SIGNER_PHONE},  FIXED_SIGNER_PHONE)
     , FIXED_IRS_NO        = #DB_OWNER#nvl(${FIXED_IRS_NO},        FIXED_IRS_NO)
     , FIXED_CATEGORY      = #DB_OWNER#nvl(${FIXED_CATEGORY},      FIXED_CATEGORY)
WHERE HOUSE_CODE   = ${session.HOUSE_CODE}
  AND CONT_NO      = ${CONT_NO}
  AND CONT_GL_SEQ  = ${CONT_GL_SEQ}
  AND SIGNER_ID    = ${SIGNER_ID}


UPDATE SSCSI
   SET DEL_FLAG = 'Y'
     , CHANGE_DATE = ${current.DATE}
     , CHANGE_TIME = ${current.TIME}
     , CHANGE_USER_ID = ${session.ID}
WHERE HOUSE_CODE   = ${session.HOUSE_CODE}
  AND CONT_NO      = ${CONT_NO}
  AND CONT_GL_SEQ  = ${CONT_GL_SEQ}


DELETE
  FROM SSCSI
WHERE HOUSE_CODE   = ${session.HOUSE_CODE}
  AND CONT_NO      = ${CONT_NO}
  AND CONT_GL_SEQ  = ${CONT_GL_SEQ}


SELETE *
  FROM SSCSI
WHERE HOUSE_CODE   = ${session.HOUSE_CODE}
  AND CONT_NO      = ${CONT_NO}
  AND CONT_GL_SEQ  = ${CONT_GL_SEQ}


SELECT USER_ID
     , COMPANY_CODE
FROM SUSMT
WHERE HOUSE_CODE    = ${session.HOUSE_CODE}
  AND COMPANY_CODE  = ${session.COMPANY_CODE}
  AND WORK_TYPE     = 'Z'


SELECT HOUSE_CODE
	, COMPANY_CODE
	, CONT_NO
	, CONT_GL_SEQ
	, CONT_FORM_NO
	, ITEM_VALUE
FROM SCTTI
WHERE HOUSE_CODE	 = ${session.HOUSE_CODE}
	AND COMPANY_CODE = ${session.COMPANY_CODE}
	AND CONT_NO      = ${CONT_NO}
	AND CONT_GL_SEQ  = ${CONT_GL_SEQ}
	AND CONT_FORM_NO = $S{CONT_FORM_NO}
	AND #DB_OWNER#nvl(DEL_FLAG, 'N') = 'N'


UPDATE SCTTI
  SET ITEM_VALUE      = ${ITEM_VALUE}
     , ADD_DATE       = ${current.DATE}
     , ADD_TIME       = ${current.TIME}
     , ADD_USER_ID    = ${session.ID}
     , CONT_FORM_NO   = #DB_OWNER#nvl(${CONT_FORM_NO}, NULL)
     , CHANGE_DATE    = ${current.DATE}
     , CHANGE_TIME    = ${current.TIME}
     , CHANGE_USER_ID = ${session.ID}
WHERE HOUSE_CODE     = ${session.HOUSE_CODE}
	AND COMPANY_CODE = ${session.COMPANY_CODE}
	AND CONT_NO      = ${CONT_NO}
	AND CONT_GL_SEQ  = ${CONT_GL_SEQ}


INSERT
  INTO SCTTI (
       HOUSE_CODE
     , COMPANY_CODE
     , CONT_NO
     , CONT_GL_SEQ
     , CONT_FORM_NO
     , ITEM_VALUE
     , ADD_DATE
     , ADD_TIME
     , ADD_USER_ID
     , CHANGE_DATE
     , CHANGE_TIME
     , CHANGE_USER_ID
     , DEL_FLAG
  )
VALUES (
       ${session.HOUSE_CODE}
     , ${session.COMPANY_CODE}
     , ${CONT_NO}
     , ${CONT_GL_SEQ}
     , #DB_OWNER#nvl(${CONT_FORM_NO}, '')
     , ${ITEM_VALUE}
     , ${current.DATE}
     , ${current.TIME}
     , ${session.ID}
     , ${current.DATE}
     , ${current.TIME}
     , ${session.ID}
     , 'N'
)


        INSERT INTO SMCWT
        (
			  HOUSE_CODE
			, COMPANY_CODE
			, DOC_NUMBER
			, ADD_DATE
			, ADD_TIME
			, ADD_USER_ID
			, CHANGE_DATE
			, CHANGE_TIME
			, CHANGE_USER_ID
			, DATA
            , POSTPROCESSED
            , PRC_TYPE
            , ATTACH_NUMBER
		) VALUES (
			  ${session.HOUSE_CODE  }
			, ${session.COMPANY_CODE}
			, ${DOC_NUMBER          }
			, ${current.DATE        }
			, ${current.TIME        }
			, ${session.ID          }
			, ${current.DATE        }
			, ${current.TIME        }
			, ${session.ID          }
			, ${DATA				}
            , ${POSTPROCESSED       }
            , ${PRC_TYPE            }
            , ${ATTACH_NUMBER       }
		)


        UPDATE
        	SMCWT
        SET
			CHANGE_DATE 		= ${current.DATE}
			, CHANGE_TIME 		= ${current.TIME}
			, CHANGE_USER_ID	= ${session.ID}
			, DATA 				= ${DATA}
		WHERE
			HOUSE_CODE 			= ${session.HOUSE_CODE}
			AND COMPANY_CODE	= ${session.COMPANY_CODE}
			AND DOC_NUMBER 		= ${DOC_NUMBER}


DELETE FROM SMCWT
WHERE HOUSE_CODE    = ${session.HOUSE_CODE}
  AND COMPANY_CODE  = ${session.COMPANY_CODE}
  AND DOC_NUMBER    = ${DOC_NUMBER}


UPDATE SMCWT SET
      CHANGE_DATE       = ${current.DATE}
    , CHANGE_TIME       = ${current.TIME}
    , CHANGE_USER_ID    = ${session.ID}
    , POSTPROCESSED     = ${POSTPROCESSED}
WHERE HOUSE_CODE        = ${session.HOUSE_CODE}
  AND COMPANY_CODE      = ${session.COMPANY_CODE}
  AND DOC_NUMBER        = ${DOC_NUMBER}


SELECT USER_ID
	,USER_NAME_LOC
	,EMAIL
FROM SUSMT
WHERE HOUSE_CODE        = ${session.HOUSE_CODE}
  AND USER_ID           = ${SIGNER_ID}
  AND USER_NAME_LOC		= ${SIGNER_NAME}


UPDATE SCTGL
   SET CHANGE_DATE    = ${current.DATE}
     , CHANGE_TIME    = ${current.TIME}
     , CHANGE_USER_ID = ${session.ID}
     , STATUS         = ${STATUS}
WHERE HOUSE_CODE   = ${session.HOUSE_CODE}
  AND CONT_NO      = ${CONT_NO}
  AND CONT_GL_SEQ  = ${CONT_GL_SEQ}
